STEP_HEADS = ["*3 أسباب* لازم تعرفها", "ليش *يصير كذا*؟", "*الصورة* من الداخل", "*3 أشياء* تفرق"]
CMP_HEADS = ["*الفكرة* بوضوح", "الشائع *والحقيقة*", "*الحقيقة* اللي ما تنقال"]
FOLLOW = [("احفظ المقطع وشاركه", "تابع *ترس* عشان تستفيد"), ("شاركه مع أحد يحتاجه", "تابع *ترس* للمزيد"), ("لا تفوتك الحلقة الجاية", "تابع *ترس* الحين")]
TAGS_ROT = [["#سيرة_ذاتية", "#مقابلة_شخصية"], ["#رواتب", "#بيئة_العمل"], ["#تطوير_الذات", "#لينكدان"], ["#خريجين", "#موارد_بشرية"]]


def item(n, v):
    em, hs, hb, why, pts, bad, good, cq, cw = v
    plain = lambda s: s.replace("*", "")
    scenes = [
        {"type": "hook", "small": hs, "big": hb, "emoji": em},
        {"type": "why", "small": "الحقيقة", "big": why, "emoji": "💡"},
        {"type": "steps", "small": "خلني أوضح لك", "big": STEP_HEADS[n % 4], "title": "النقاط المهمة", "items": pts.split("|")},
        {"type": "compare", "small": "باختصار", "big": CMP_HEADS[n % 3], "bad": bad, "good": good, "badLabel": "اللي يظنه الكل", "goodLabel": "الحقيقة"},
        {"type": "comment", "small": cq, "big": f"اكتب «*{cw}*» بالتعليقات", "word": cw},
        {"type": "follow", "small": FOLLOW[n % 3][0], "big": FOLLOW[n % 3][1]},
    ]
    q = f"{plain(hs)} {plain(hb)}"
    tags = ["#وظائف", "#وظائف_السعودية", "#توظيف"] + TAGS_ROT[n % 4] + ["#اكسبلور"]
    cap = f"{q} 🤔 {plain(why)}. وش رأيك؟ " + " ".join(tags)
    if len(cap) > 220:
        cap = f"{q} 🤔 وش رأيك؟ " + " ".join(tags)
    return {"id": None, "num": n + 1, "label": f"الحلقة <b>{n+1}</b> · سوق التوظيف", "scenes": scenes,
            "caption": cap, "title": plain(f"{hs} {hb}")}


def build(start):
    d0 = datetime.date.fromisoformat(start)
    out = []
    for day in range(30):
        date = (d0 + datetime.timedelta(days=day)).isoformat()
        items = []
        for j in range(3):
            n = day * 3 + j
            it = item(n, V[n]); it["id"] = f"{j+1:02d}"
            items.append(it)
        p = f"engine/v2-{date}.json"
        json.dump(items, open(p, "w"), ensure_ascii=False, indent=1)
        out.append(p)
    return out


if __name__ == "__main__":
    fs = build(sys.argv[1]); print(len(fs), fs[0], fs[-1])
